package com.example.afktracker;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup("danksafktracker")
public interface AfkTrackerConfig extends Config {
    @Range(min=1,max=60)
    @ConfigItem(keyName="idleDelayMinutes",name="AFK starts after (minutes)",description="No clicks inside the RuneLite client for this long.",position=1)
    default int idleDelayMinutes() { return 5; }

    @ConfigItem(keyName="showOverlay",name="Show overlay",description="Show the AFK tracker on screen.",position=2)
    default boolean showOverlay() { return true; }

    @ConfigItem(keyName="trackMovement",name="Mouse movement resets timer",description="Normally only clicks reset the idle timer.",position=3)
    default boolean trackMovement() { return false; }
}

package com.example.afktracker;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;

/** Visual-only replacement for the V3 overlay. Timer logic stays in AfkTrackerPlugin. */
public class AfkTrackerOverlay extends OverlayPanel
{
    private static final int W = 248;
    private static final int H = 228;
    private static final Color BACK = new Color(13, 20, 19, 128);
    private static final Color CARD = new Color(27, 40, 35, 166);
    private static final Color LIME = new Color(164, 246, 107);
    private static final Color WHITE = new Color(241, 246, 240);
    private static final Color MUTED = new Color(161, 176, 166);
    private static final Color BORDER = new Color(55, 80, 65);
    private final AfkTrackerPlugin plugin;
    private final AfkTrackerConfig config;

    @Inject
    public AfkTrackerOverlay(AfkTrackerPlugin plugin, AfkTrackerConfig config)
    {
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.TOP_LEFT);
        setMovable(true);
        panelComponent.setPreferredSize(new Dimension(W, H));
    }

    @Override
    public Dimension render(Graphics2D g)
    {
        if (!config.showOverlay()) return null;
        Object oldAA = g.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
        Font oldFont = g.getFont();
        Color oldColor = g.getColor();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        try
        {
            g.setColor(BACK);
            g.fillRoundRect(0, 0, W, H, 12, 12);
            g.setColor(BORDER);
            g.setStroke(new BasicStroke(1f));
            g.drawRoundRect(0, 0, W - 1, H - 1, 12, 12);

            g.setFont(new Font("SansSerif", Font.BOLD, 12));
            draw(g, "DANK'S AFK TRACKER", 12, 21, LIME);
            boolean logged = plugin.isSessionActive();
            boolean afk = logged && plugin.isIdle();
            String status = !logged ? "OFFLINE" : afk ? "AFK" : "ACTIVE";
            g.setFont(new Font("SansSerif", Font.BOLD, 10));
            int badgeWidth = g.getFontMetrics().stringWidth(status) + 14;
            int badgeX = W - badgeWidth - 10;
            g.setColor(new Color(42, 68, 45, 185));
            g.fillRoundRect(badgeX, 9, badgeWidth, 18, 9, 9);
            draw(g, status, badgeX + 7, 22, LIME);

            g.setColor(BORDER);
            g.drawLine(12, 34, W - 12, 34);
            center(g, "CURRENT AFK", 54, MUTED, new Font("SansSerif", Font.PLAIN, 10));
            center(g, format(plugin.getCurrentAfkMs()), 91, LIME, new Font("SansSerif", Font.BOLD, 30));
            center(g, "Starts after " + config.idleDelayMinutes() + " min without a click", 109,
                MUTED, new Font("SansSerif", Font.PLAIN, 10));

            tile(g, 10, 122, "SESSION", format(plugin.getSessionMs()));
            tile(g, 126, 122, "ACTIVE", format(plugin.getActiveMs()));
            tile(g, 10, 168, "TOTAL AFK", format(plugin.getTotalAfkMs()));
            tile(g, 126, 168, "LONGEST AFK", format(plugin.getLongestAfkMs()));
            g.setFont(new Font("SansSerif", Font.PLAIN, 10));
            draw(g, "No click", 12, 221, MUTED);
            right(g, format(plugin.getSinceClickMs()), W - 12, 221, WHITE);
            return new Dimension(W, H);
        }
        finally
        {
            g.setFont(oldFont);
            g.setColor(oldColor);
            if (oldAA != null) g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, oldAA);
        }
    }

    private void tile(Graphics2D g, int x, int y, String title, String value)
    {
        g.setColor(CARD);
        g.fillRoundRect(x, y, 112, 41, 8, 8);
        g.setFont(new Font("SansSerif", Font.PLAIN, 10));
        draw(g, title, x + 9, y + 15, MUTED);
        g.setFont(new Font("SansSerif", Font.BOLD, 14));
        draw(g, value, x + 9, y + 33, WHITE);
    }

    private static void draw(Graphics2D g, String s, int x, int baseline, Color c)
    {
        g.setColor(c);
        g.drawString(s, x, baseline);
    }
    private static void center(Graphics2D g, String s, int baseline, Color c, Font f)
    {
        g.setFont(f);
        FontMetrics fm = g.getFontMetrics();
        draw(g, s, (W - fm.stringWidth(s)) / 2, baseline, c);
    }
    private static void right(Graphics2D g, String s, int right, int baseline, Color c)
    {
        draw(g, s, right - g.getFontMetrics().stringWidth(s), baseline, c);
    }
    private static String format(long ms)
    {
        long seconds = Math.max(0, ms) / 1000;
        long hours = seconds / 3600;
        long minutes = (seconds / 60) % 60;
        long remainder = seconds % 60;
        return hours > 0 ? String.format("%d:%02d:%02d", hours, minutes, remainder)
            : String.format("%d:%02d", seconds / 60, remainder);
    }
}

package com.example.afktracker;

import com.google.inject.Provides;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.event.MouseMotionAdapter;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(name = "Dank's AFK Tracker", description = "Session-based click inactivity tracker")
public class AfkTrackerPlugin extends Plugin
{
    @Inject private Client client;
    @Inject private OverlayManager overlayManager;
    @Inject private AfkTrackerOverlay overlay;
    @Inject private AfkTrackerConfig config;

    private long sessionStart;
    private long lastClick;
    private long lastSample;
    private long totalAfk;
    private long longestAfk;
    private boolean sessionActive;

    private final MouseAdapter clickListener = new MouseAdapter()
    {
        @Override public void mousePressed(MouseEvent e) { recordInteraction(); }
    };
    private final MouseMotionAdapter motionListener = new MouseMotionAdapter()
    {
        @Override public void mouseMoved(MouseEvent e) { if (config.trackMovement()) recordInteraction(); }
        @Override public void mouseDragged(MouseEvent e) { if (config.trackMovement()) recordInteraction(); }
    };

    @Provides AfkTrackerConfig provideConfig(ConfigManager manager)
    {
        return manager.getConfig(AfkTrackerConfig.class);
    }

    @Override protected void startUp()
    {
        synchronized (this)
        {
            resetSession();
            if (client.getGameState() == GameState.LOGGED_IN) beginSession();
        }
        client.getCanvas().addMouseListener(clickListener);
        client.getCanvas().addMouseMotionListener(motionListener);
        overlayManager.add(overlay);
    }

    @Override protected void shutDown()
    {
        client.getCanvas().removeMouseListener(clickListener);
        client.getCanvas().removeMouseMotionListener(motionListener);
        overlayManager.remove(overlay);
        synchronized (this) { resetSession(); }
    }

    @Subscribe public void onGameStateChanged(GameStateChanged event)
    {
        synchronized (this)
        {
            if (event.getGameState() == GameState.LOGGED_IN)
            {
                if (!sessionActive) beginSession();
            }
            else if (event.getGameState() == GameState.LOGIN_SCREEN
                || event.getGameState() == GameState.LOGIN_SCREEN_AUTHENTICATOR
                || event.getGameState() == GameState.CONNECTION_LOST)
            {
                resetSession();
            }
            // LOADING/HOPPING are transitional states; don't reset for them.
        }
    }

    private void beginSession()
    {
        resetSession();
        long now = System.nanoTime();
        sessionStart = lastClick = lastSample = now;
        sessionActive = true;
    }

    private void resetSession()
    {
        sessionStart = lastClick = lastSample = totalAfk = longestAfk = 0L;
        sessionActive = false;
    }

    private synchronized void recordInteraction()
    {
        if (!sessionActive) return;
        long now = System.nanoTime();
        sample(now);
        longestAfk = Math.max(longestAfk, Math.max(0L, now - lastClick - delayNanos()));
        lastClick = now;
    }

    private void sample(long now)
    {
        if (!sessionActive) return;
        long afkStart = Math.max(lastSample, lastClick + delayNanos());
        totalAfk += Math.max(0L, now - afkStart);
        lastSample = now;
    }

    private long delayNanos() { return config.idleDelayMinutes() * 60_000_000_000L; }
    private long elapsed(long now) { return sessionActive ? Math.max(0L, now - sessionStart) : 0L; }
    private long currentAfk(long now) { return sessionActive ? Math.max(0L, now - lastClick - delayNanos()) : 0L; }
    private long totalAfk(long now)
    {
        if (!sessionActive) return 0L;
        return totalAfk + Math.max(0L, now - Math.max(lastSample, lastClick + delayNanos()));
    }
    private static long ms(long nanos) { return nanos / 1_000_000L; }

    public synchronized boolean isSessionActive() { return sessionActive; }
    public synchronized boolean isIdle() { return sessionActive && currentAfk(System.nanoTime()) > 0L; }
    public synchronized long getSinceClickMs() { return sessionActive ? ms(Math.max(0L, System.nanoTime() - lastClick)) : 0L; }
    public synchronized long getCurrentAfkMs() { return ms(currentAfk(System.nanoTime())); }
    public synchronized long getTotalAfkMs() { return ms(totalAfk(System.nanoTime())); }
    public synchronized long getLongestAfkMs() { return ms(Math.max(longestAfk, currentAfk(System.nanoTime()))); }
    public synchronized long getSessionMs() { return ms(elapsed(System.nanoTime())); }
    public synchronized long getActiveMs()
    {
        long now = System.nanoTime();
        return ms(Math.max(0L, elapsed(now) - totalAfk(now)));
    }
}
